import * as C from './credit.js';
import * as O from './objectives.js';
import {cleanLiveAnalyticsPossession_,buildLiveAnalyticsSummary_,buildLiveReviewInsights_,buildLiveNextAdjustment_,buildGameScoutingComparison_} from './engine.js';
import {buildReportContext,reportFingerprint,buildHuddleBrief} from './insights.js';
export const VERSION='2026.10.30.6';
export const TAGS=[['paintTouch','Paint touch'],['offensiveRebound','OREB'],['transition','Transition'],['cut','Cut'],['driveKick','Drive & kick'],['setPlay','Set play'],['ato','ATO'],['deflection','Deflection'],['putback','Putback'],['pickRoll','Pick & roll'],['postUp','Post-up'],['isolation','Isolation'],['rightHandDrive','Right-hand drive']];
export const clone=value=>structuredClone(value);
export const id=prefix=>prefix+crypto.randomUUID();
export function blankDraft(side='offense'){return{id:id('DRAFT-'),teamSide:side,paintTouch:false,transition:false,rightHandDrive:false,offensiveRebounds:0,playEvents:[],jersey:''};}
export function roster(text){const lines=String(text||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.length>20)throw Error('Up to twenty players per roster.');const seen=new Set();return lines.map((line,index)=>{const m=line.match(/^#?(\d{1,3})\s*[,\t ]\s*(.+)$/);if(!m)throw Error('Roster line '+(index+1)+': use “12, Player Name”.');if(seen.has(m[1]))throw Error('Duplicate jersey #'+m[1]);seen.add(m[1]);return{jersey:m[1],name:m[2].trim().slice(0,80)};});}
export function cleanFocus(focus){if(!Array.isArray(focus)||focus.length>6)throw Error('Choose up to six focus tags.');const seen=new Set();return focus.map(t=>{const label=t.type==='customTag'?String(t.label||'').trim():TAGS.find(x=>x[0]===t.type)?.[1];if(!label||label.length>40||/[\x00-\x1f]/.test(label))throw Error('Choose a valid tag name.');const key=t.type+':'+label;if(seen.has(key))throw Error('Choose each focus tag once.');seen.add(key);return{type:t.type,label};});}
export function cleanFocusBySide(value,fallback){const shared=cleanFocus(fallback??[{type:'paintTouch'},{type:'offensiveRebound'}]);if(value==null)return{offense:cleanFocus(shared),defense:cleanFocus(shared)};if(typeof value!=='object'||Array.isArray(value)||!Array.isArray(value.offense)||!Array.isArray(value.defense))throw Error('Choose offense and defense tag lists.');return{offense:cleanFocus(value.offense),defense:cleanFocus(value.defense)};}
export function focusForSide(g,side=g.draft?.teamSide||'offense'){return cleanFocusBySide(g.focusBySide,g.focus)[side];}
export function focusCatalogForGame(g){const all=cleanFocusBySide(g.focusBySide,g.focus),seen=new Set();return [...all.offense,...all.defense].filter(t=>{const key=t.type+':'+t.label;if(seen.has(key))return false;seen.add(key);return true;});}
export function setFocusBySide(g,value){live(g);if(g.draft.playEvents.length||g.draft.transition||g.draft.rightHandDrive)throw Error('Finish this possession before changing focus.');g.focusBySide=cleanFocusBySide(value,g.focus);g.focus=cleanFocus(g.focusBySide.offense);}
export function createGame(data,prepared=null){if(!data.team?.trim()||!data.opponent?.trim())throw Error('Enter our team and the opponent.');return{format:'coachiq-offline-game',schema:1,id:id('OFFGAME-'),importId:id('OFFIMPORT-'),revision:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),team:data.team.slice(0,200),opponent:data.opponent.trim().slice(0,80),gameDate:data.gameDate,gameFormat:data.gameFormat==='Halves'?'Halves':'Quarters',periodLength:Number(data.periodLength)||8,period:1,status:'live',ourRoster:data.ourRoster||[],opponentRoster:data.opponentRoster||[],objectives:O.clean(data.objectives??prepared?.objectives),objectiveEvents:[],focus:cleanFocus(data.focus||[{type:'paintTouch'},{type:'offensiveRebound'}]),focusBySide:cleanFocusBySide(data.focusBySide??prepared?.focusBySide,data.focus??prepared?.focus),autoSwitch:true,creditSettings:C.settings(),pendingCredit:null,draft:blankDraft(),draftHistory:[],possessions:[],markers:[],corrections:[],scoreAdjustments:[],scouting:prepared?.scouting||null,scoutingWatchlist:prepared?.scoutingWatchlist||[],season:prepared?.season||'',preparationId:prepared?.preparationId||null,quickStats:['score','ppp','paint','rebounds','kills','turnovers'],transferLocked:false,reportCheckpoints:[]};}
export function activeLog(game){return game.possessions.filter(p=>!p.voided);}
export function totals(game){const analytics=buildLiveAnalyticsSummary_(activeLog(game),game.period),offset={our:0,opponent:0};game.scoreAdjustments.forEach(a=>offset[a.side]+=a.delta);return{analytics,score:{our:analytics.offense.points+offset.our,opponent:analytics.defense.points+offset.opponent}};}
function editable(g){if(g.transferLocked)throw Error('This exported result is locked. Make later corrections in CoachIQ after importing it.');}
function live(g){editable(g);if(g.pendingCredit)throw Error("Finish or skip the player prompt first.");if(g.status!=='live')throw Error('This game is finished. Use Review to correct a possession.');}
function credited(type,jersey,side,label){if(jersey&&!/^\d{1,3}$/.test(jersey))throw Error('Use a jersey number of 1–3 digits.');return{type,jersey:jersey||'',label:label||'',playerSide:['deflection','foulRetained','foulFreeThrows'].includes(type)?(side==='defense'?'us':'opponent'):(side==='offense'?'us':'opponent')};}
export function tapTag(g,tag){live(g);const d=g.draft;if(tag.type==='rightHandDrive'&&d.teamSide!=='defense')return;if(d.playEvents.length>=99)throw Error('Finish this possession before adding more plays.');g.draftHistory.push(clone(d));g.draftHistory=g.draftHistory.slice(-100);if(tag.type==='transition'||tag.type==='rightHandDrive'){d[tag.type]=!d[tag.type];return;}if(tag.type==='offensiveRebound'){if(d.offensiveRebounds>=10)throw Error('Up to ten offensive rebounds per possession.');d.offensiveRebounds++;}else if(tag.type==='paintTouch')d.paintTouch=true;else{const at=d.playEvents.findIndex(e=>e.type===tag.type&&(tag.type!=='customTag'||e.label===tag.label));if(at>=0){d.playEvents.splice(at,1);return;}}d.playEvents.push(credited(tag.type,d.jersey,d.teamSide,tag.label));}
export function hasFreeThrows(d){return d.freeThrows===true||(d.playEvents||[]).some(e=>['freeThrows','ftMade','ftMiss'].includes(e.type));}
export function freeThrowSummary(d){const events=d.playEvents||[];return{made:events.filter(e=>e.type==='ftMade').length,attempted:events.filter(e=>e.type==='ftMade'||e.type==='ftMiss').length,points:events.reduce((n,e)=>n+(e.type==='ftMade'?1:/^made[123]$/.test(e.type)?Number(e.type.slice(-1)):0),0)};}
function rememberPlay(g){g.draftHistory.push(clone(g.draft));g.draftHistory=g.draftHistory.slice(-100);}
export function startFreeThrows(g){live(g);if(hasFreeThrows(g.draft))return;if(g.draft.playEvents.length>=98)throw Error('Finish this possession before adding more plays.');rememberPlay(g);g.draft.freeThrows=true;g.draft.playEvents.push(credited('freeThrows',g.draft.jersey,g.draft.teamSide));}
export function recordFoul(g,outcome){live(g);if(!['retained','freeThrows'].includes(outcome))throw Error('Choose keeps ball or free throws.');if(g.draft.playEvents.length>=97)throw Error('Finish this possession before adding more plays.');rememberPlay(g);g.draft.playEvents.push(credited(outcome==='retained'?'foulRetained':'foulFreeThrows','',g.draft.teamSide));if(outcome==='freeThrows'&&!hasFreeThrows(g.draft)){g.draft.freeThrows=true;g.draft.playEvents.push(credited('freeThrows',g.draft.jersey,g.draft.teamSide));}}
export function recordFreeThrow(g,made){live(g);if(typeof made!=='boolean')throw Error('Choose FT made or FT missed.');if(!hasFreeThrows(g.draft))throw Error('Choose Free throws first.');if(g.draft.playEvents.length>=98)throw Error('Finish this possession before adding more plays.');if(made&&freeThrowSummary(g.draft).points>=20)throw Error('Check this possession: maximum 20 points.');rememberPlay(g);g.draft.playEvents.push(credited(made?'ftMade':'ftMiss',g.draft.jersey,g.draft.teamSide));}
export function addFreeThrowBasket(g,points){live(g);if(!hasFreeThrows(g.draft)||![2,3].includes(points))throw Error('Choose a made 2 or made 3 during the FT possession.');if(g.draft.playEvents.length>=97||freeThrowSummary(g.draft).points+points>20)throw Error('Check this possession before adding another basket.');rememberPlay(g);if(!freeThrowSummary(g.draft).attempted&&!g.draft.playEvents.some(e=>/^made[123]$/.test(e.type)))g.draft.playEvents.push(credited('andOne',g.draft.jersey,g.draft.teamSide));g.draft.playEvents.push(credited('made'+points,g.draft.jersey,g.draft.teamSide));}
export function finishFreeThrows(g,draftId){return finishPossession(g,freeThrowSummary(g.draft).points,false,draftId);}
export function finishPossession(g,points,turnover=false,draftId){if(draftId&&g.draft.id!==draftId)return false;live(g);const d=g.draft,payload={...d,points:Number(points),period:g.period,possessionId:id('LAP-'),trackedTags:focusForSide(g,d.teamSide).map(t=>t.type),playEvents:clone(d.playEvents)};if(hasFreeThrows(d)){const ft=freeThrowSummary(d);if(!ft.attempted)throw Error('Record an FT make/miss, or use Undo tag to cancel Free throws.');if(Number(points)!==ft.points)throw Error('Use the counted free-throw/basket total to finish.');}else if(points>0)payload.playEvents.push(credited('made'+points,d.jersey,d.teamSide));if(turnover)payload[d.teamSide==='offense'?'turnover':'forcedTurnover']=true;const clean=cleanLiveAnalyticsPossession_(payload,g.period);g.possessions.push({...clean,sequence:g.possessions.length+1,timestamp:new Date().toISOString(),revision:0});g.pendingCredit=C.shouldPrompt(g,clean)?clean.possessionId:null;g.draft=blankDraft(g.autoSwitch?(d.teamSide==='offense'?'defense':'offense'):d.teamSide);g.draftHistory=[];return true;}
export function undoDraft(g){live(g);if(!g.draftHistory.length)throw Error('No tag to undo in this possession.');g.draft=g.draftHistory.pop();}
export function undoPossession(g){live(g);const latest=activeLog(g).at(-1);if(!latest)throw Error('No saved possession to undo.');const before=clone(latest);latest.voided=true;g.corrections.push({id:id('EDIT-'),possessionId:latest.possessionId,kind:'void',reason:'Undo latest possession',at:new Date().toISOString(),before});}
export function switchSide(g,side){live(g);if(g.draft.playEvents.length||g.draft.transition||g.draft.rightHandDrive)throw Error('Finish this possession or undo its tags before switching sides.');g.draft=blankDraft(side);g.draftHistory=[];}
export function advancePeriod(g){live(g);if(g.draft.playEvents.length||g.draft.transition||g.draft.rightHandDrive)throw Error('Finish the current possession before ending the period.');if(g.period>=20)throw Error('Maximum period reached.');g.period++;}
export function addMarker(g,label,side){live(g);if(!String(label).trim())throw Error('Name the adjustment.');if(g.markers.length>=20)throw Error('Up to twenty adjustment markers per game.');g.markers.push({kind:'tactical',adjustmentId:id('TACTIC-'),label:String(label).trim().slice(0,80),side:['offense','defense','both'].includes(side)?side:'defense',boundarySequence:g.possessions.length,period:g.period,changedAt:new Date().toISOString()});}
export function correctPossession(g,pid,data,reason){editable(g);if(!reason?.trim())throw Error('A correction reason is required.');const original=g.possessions.find(p=>p.possessionId===pid&&!p.voided);if(!original)throw Error('Possession not found.');if(data.teamSide!==original.teamSide)throw Error('A correction cannot change offense/defense.');const clean=cleanLiveAnalyticsPossession_({...data,possessionId:pid,trackedTags:original.trackedTags},original.period),after={...original,...clean,revision:(original.revision||0)+1};g.corrections.push({id:id('EDIT-'),possessionId:pid,reason:reason.trim().slice(0,240),at:new Date().toISOString(),before:clone(original),after:clone(after)});Object.assign(original,after);}
export function finishGame(g,our,opponent){live(g);if(g.draft.playEvents.length||g.draft.transition||g.draft.rightHandDrive)throw Error('Finish the current possession first.');if(!Number.isInteger(our)||!Number.isInteger(opponent)||our<0||opponent<0||our===opponent)throw Error('Enter valid final scores with a winner.');g.status='completed';g.finalScore={our,opponent};g.completedAt=new Date().toISOString();}
export function recordReportCheckpoint(g,kind='timeout',period=g.period){if(!['timeout','period','postgame'].includes(kind)||!Number.isInteger(period)||period<1||period>20)throw Error('Choose a valid report checkpoint.');const checkpoints=g.reportCheckpoints||(g.reportCheckpoints=[]),fingerprint=reportFingerprint(g,kind,period),last=checkpoints.at(-1);if(last?.fingerprint===fingerprint&&last.kind===kind&&last.period===period){g.lastReportReused=true;return last.id;}const context=buildReportContext(g,{kind,period}),offsets={our:0,opponent:0};g.scoreAdjustments.forEach(a=>offsets[a.side]+=a.delta);const checkpoint={id:id('REPORT-'),kind,period,boundarySequence:g.possessions.length,at:new Date().toISOString(),fingerprint,correctionCount:g.corrections.length,snapshot:{...context.snapshot,offsets,objectivePlan:clone(g.objectives||[]),objectiveEventCount:(g.objectiveEvents||[]).length}};checkpoints.push(checkpoint);g.reportCheckpoints=checkpoints.slice(-200);g.lastReportReused=false;return checkpoint.id;}
export function gameReport(g,options={}){const checkpoint=options.checkpointId?(g.reportCheckpoints||[]).find(c=>c.id===options.checkpointId):null,period=options.period??checkpoint?.period??g.period,log=activeLog(g).filter(p=>!checkpoint||p.sequence<=checkpoint.boundarySequence),analytics=buildLiveAnalyticsSummary_(log,period),offset={our:0,opponent:0};g.scoreAdjustments.forEach(a=>offset[a.side]+=a.delta);const offsets=checkpoint?.snapshot?.offsets||offset,score=g.finalScore&&(!checkpoint||checkpoint.kind==='postgame')?g.finalScore:{our:analytics.offense.points+offsets.our,opponent:analytics.defense.points+offsets.opponent},review=buildLiveReviewInsights_(log,g.markers),decision=buildLiveNextAdjustment_(analytics,g.scoutingWatchlist||[],analytics.intelligence.recommendations,[]),scout=g.scouting?buildGameScoutingComparison_(g.scouting,{analytics,finalScore:g.finalScore},'offline'):null;return{analytics,score,review,decision,scout,objectiveGame:{...g,possessions:log,objectives:checkpoint?(checkpoint.snapshot.objectivePlan||[]):g.objectives,objectiveEvents:checkpoint?(g.objectiveEvents||[]).slice(0,checkpoint.snapshot.objectiveEventCount||0):g.objectiveEvents},context:options.context===false?null:buildReportContext(g,{...options,period,overallDecision:decision.nextAdjustment})};}

export function validateImportedGame(value){if(!value||typeof value!=='object')throw Error('Invalid backup file.');if(!value||value.format!=='coachiq-offline-game'||value.schema!==1||!/^OFFGAME-[a-f0-9-]{36}$/i.test(value.id)||!/^OFFIMPORT-[a-f0-9-]{36}$/i.test(value.importId))throw Error('This is not a supported GameDay backup.');if(!String(value.team||'').trim()||!String(value.opponent||'').trim()||!/^\d{4}-\d{2}-\d{2}$/.test(value.gameDate||'')||!Number.isInteger(value.period)||value.period<1||value.period>20)throw Error('Invalid saved game details.');if(!Array.isArray(value.possessions)||value.possessions.length>2000||!Array.isArray(value.markers)||value.markers.length>20)throw Error('Game backup exceeds the supported limits.');value.focus=cleanFocus(value.focus);if(value.focusBySide!=null)value.focusBySide=cleanFocusBySide(value.focusBySide,value.focus);const seen=new Set();value.possessions=value.possessions.map((p,i)=>{if(seen.has(p.possessionId))throw Error('Duplicate possession ID in backup.');seen.add(p.possessionId);return{...p,...cleanLiveAnalyticsPossession_(p,p.period),sequence:i+1,voided:p.voided===true,revision:Number(p.revision)||0};});if(!['live','completed'].includes(value.status))throw Error('Invalid game status.');if(value.status==='completed'&&(!Number.isInteger(value.finalScore?.our)||!Number.isInteger(value.finalScore?.opponent)||value.finalScore.our<0||value.finalScore.opponent<0||value.finalScore.our===value.finalScore.opponent))throw Error('Invalid final score.');if(!value.draft||!['offense','defense'].includes(value.draft.teamSide)||!Array.isArray(value.draft.playEvents))throw Error('Invalid saved draft.');value.draftHistory=Array.isArray(value.draftHistory)?value.draftHistory.slice(-100):[];value.corrections=Array.isArray(value.corrections)?value.corrections:[];value.scoreAdjustments=Array.isArray(value.scoreAdjustments)?value.scoreAdjustments:[];if(value.scoreAdjustments.length>200||value.scoreAdjustments.some(a=>!a||!['our','opponent'].includes(a.side)||!Number.isInteger(a.delta)||!a.delta||Math.abs(a.delta)>10))throw Error('Invalid score adjustment in backup.');if(value.markers.some((m,i)=>!m||m.kind!=='tactical'||!Number.isInteger(m.boundarySequence)||m.boundarySequence<0||m.boundarySequence>value.possessions.length||!['offense','defense','both'].includes(m.side)||(i>0&&m.boundarySequence<value.markers[i-1].boundarySequence)))throw Error('Invalid adjustment markers in backup.');if(value.transferLocked&&value.status!=='completed')throw Error('A live game cannot be export-locked.');if(value.corrections.length>2000||value.corrections.some(c=>!c||typeof c.reason!=='string'||!c.before))throw Error('Invalid correction history.');for(const players of [value.ourRoster,value.opponentRoster])if(!Array.isArray(players)||players.length>20||players.some(p=>!p||!/^\d{1,3}$/.test(String(p.jersey||''))||!String(p.name||'').trim()))throw Error('Invalid roster in backup.');if(value.reportCheckpoints!=null){if(!Array.isArray(value.reportCheckpoints)||value.reportCheckpoints.length>200||new Set(value.reportCheckpoints.map(c=>c?.id)).size!==value.reportCheckpoints.length||value.reportCheckpoints.some((c,i)=>!c||!/^REPORT-[a-f0-9-]{36}$/i.test(c.id)||!['timeout','period','postgame'].includes(c.kind)||!Number.isInteger(c.boundarySequence)||c.boundarySequence<0||c.boundarySequence>value.possessions.length||!Number.isInteger(c.period)||c.period<1||c.period>20||c.period>value.period||(i>0&&c.boundarySequence<value.reportCheckpoints[i-1].boundarySequence)||typeof c.fingerprint!=='string'||c.fingerprint.length>100||!Number.isInteger(c.correctionCount)||c.correctionCount<0||!Array.isArray(c.snapshot?.issues)||c.snapshot.issues.length>6||c.snapshot.issues.some(i=>!i||typeof i.key!=='string'||!i.key||i.key.length>200||!['offense','defense'].includes(i.side)||!Number.isFinite(i.value))||(c.snapshot.offsets&&(!Number.isFinite(c.snapshot.offsets.our)||!Number.isFinite(c.snapshot.offsets.opponent)))))throw Error('Invalid report checkpoints in backup.');}value.quickStats=Array.isArray(value.quickStats)?value.quickStats:['score','ppp','paint','rebounds','kills','turnovers'];O.validateGame(value);C.validateGame(value);return value;}

export function cleanTeamLink(value){
  if(value?.format!=='coachiq-team-link'||value.schema!==1||!Array.isArray(value.teams)||!value.teams.length||value.teams.length>100)throw Error('Choose a CoachIQ team-link file.');
  const teams=value.teams.map(team=>{if(typeof team!=='string'||!team.trim()||team.length>200||/[\x00-\x1f]/.test(team))throw Error('Invalid linked team name.');return team;});
  if(new Set(teams).size!==teams.length)throw Error('Duplicate linked team name.');
  return{format:'coachiq-team-link',schema:1,teams,season:String(value.season||'').slice(0,100),schoolName:String(value.schoolName||'').slice(0,200),exportedAt:String(value.exportedAt||'')};
}
export function copyWithLinkedTeam(original,link,team){
  const clean=cleanTeamLink(link);if(!clean.teams.includes(team))throw Error('Choose a team from the imported CoachIQ names.');
  if(original.team===team&&(!clean.season||original.season===clean.season))throw Error('This game already uses that team and season.');
  const game=clone(original),ids=new Map();game.possessions.forEach(p=>{const fresh=id('LAP-');ids.set(p.possessionId,fresh);p.possessionId=fresh;});
  game.corrections.forEach(c=>{c.id=id('EDIT-');if(ids.has(c.possessionId))c.possessionId=ids.get(c.possessionId);for(const p of [c.before,c.after])if(p&&ids.has(p.possessionId))p.possessionId=ids.get(p.possessionId);});
  game.markers.forEach(m=>m.adjustmentId=id('TACTIC-'));game.scoreAdjustments.forEach(a=>a.id=id('SCORE-'));
  game.id=id('OFFGAME-');game.importId=id('OFFIMPORT-');game.revision=0;game.team=team;game.season=clean.season||game.season;game.teamLinkCorrection={sourceGameId:original.id,fromTeam:original.team,toTeam:team,at:new Date().toISOString()};if(game.scouting)game.scouting.team=team;delete game.exportedAt;return game;
}

export function huddleBrief(context){return buildHuddleBrief(context);}
